function network(id){
  const roles=[{x:155,y:90,role:'Navigator',task:'Find candidate sources'},{x:735,y:90,role:'Extractor',task:'Return supporting passages'},{x:155,y:340,role:'Aggregator',task:'Draft evidence-based answer'},{x:735,y:340,role:'Feedback loop',task:'Send evidence gaps back'}];
  return `<svg id="${id}" class="network-svg" viewBox="0 0 900 440" role="img" aria-label="INFOGENT assigns navigation, extraction, and aggregation roles. The aggregation stage sends evidence gaps back to navigation.">${roles.map((r,i)=>`<path class="flow-line" data-edge="${i+1}" d="M450 215L${r.x} ${r.y}"/><circle class="signal" data-signal="${i+1}" r="6" style="offset-path:path('M450 215L${r.x} ${r.y}')"/>`).join('')}${roles.map((r,i)=>`<g class="diagram-node" data-node="${i+1}"><rect x="${r.x-128}" y="${r.y-42}" width="256" height="84" rx="7"/><text class="role" x="${r.x}" y="${r.y-1}" text-anchor="middle">${r.role}</text><text class="task" x="${r.x}" y="${r.y+27}" text-anchor="middle">${r.task}</text></g>`).join('')}<g class="diagram-node coord" data-node="0"><circle cx="450" cy="215" r="83"/><text class="role" x="450" y="210" text-anchor="middle">Web question</text><text x="450" y="240" text-anchor="middle" style="font-size:16px">Evidence needed?</text></g><text class="svg-caption" x="450" y="432" text-anchor="middle">Specific evidence moves forward. Missing evidence moves back.</text></svg>`;
}
